import type { SplunkVisualizationBaseWithErrorHandling } from '../GlobalErrorHandler/IframeGlobalErrorHandler';
import type { DataSources } from '../common/types';

export type IframeState = {
    dataSourcesState?: {
        dataSources: DataSources;
        loading: boolean;
    };
    optionsState?: {
        options: Record<string, unknown>;
    };
    dimensionsState?: {
        width: number;
        height: number;
    };
    modeState?: {
        mode: 'view' | 'edit';
    };
    sxmlCustomViz?: SplunkVisualizationBaseWithErrorHandling;
    errorState?: string | null;
    [key: string]: unknown;
};

const subscribers: Map<string, Set<(state: IframeState[keyof IframeState]) => void>> = new Map();
const state: IframeState = {};

export function getIframeState<T extends keyof IframeState>(key: T): IframeState[T] {
    return state[key];
}

export function setIframeState<T extends keyof IframeState>(key: T, value: IframeState[T], notify = false): void {
    state[key] = value;

    if (notify) {
        const keySubscribers = subscribers.get(key as string);
        if (keySubscribers) {
            keySubscribers.forEach((callback) => callback(value));
        }
    }
}

export function subscribeToIframeState<T extends keyof IframeState>({
    key,
    callback,
    options,
}: {
    key: T;
    callback: (state: IframeState[T]) => void;
    options?: { signal?: AbortSignal; invokeImmediately?: boolean };
}): () => void {
    const keyStr = key as string;
    if (!subscribers.has(keyStr)) {
        subscribers.set(keyStr, new Set());
    }
    subscribers.get(keyStr)!.add(callback);

    if (options?.invokeImmediately) {
        const value = getIframeState(key);
        if (value !== undefined) {
            callback(value);
        }
    }

    const cleanupFunction = () => {
        const keySubscribers = subscribers.get(keyStr);
        if (keySubscribers) {
            keySubscribers.delete(callback);
        }
    };

    if (options?.signal) {
        options.signal.addEventListener('abort', cleanupFunction);
    }

    return cleanupFunction;
}
