import { registerMessageHandler } from '../../../MessageHandler/MessageHandler';
import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { TokensMessageType, type TokensUpdateMessage } from './common';

const STATE_KEY = 'tokensState';

export function handleTokensUpdate(event: MessageEvent<TokensUpdateMessage>) {
    const { data } = event.data;
    setIframeState(STATE_KEY, data, true);
}

export function initIframeTokensHandler() {
    registerMessageHandler(TokensMessageType.TokensUpdate, handleTokensUpdate);
}

export function addTokensListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}

export function getTokens(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}
