import {
    addDrilldownListener,
    handleIframeDrilldown as triggerDrilldown,
} from '../Handlers/common/DrilldownHandler/IframeDrilldownHandler';
import { addDataSourcesListener, getDataSources } from '../Handlers/studio/DataSourcesHandler/IframeDataSourcesHandler';
import { addDimensionsListener, getDimensions } from '../Handlers/studio/DimensionsHandler/IframeDimensionsHandler';
import { addErrorListener, clearError, getError, setError } from '../Handlers/studio/ErrorHandler/IframeErrorHandler';
import { addModeListener, getMode } from '../Handlers/studio/ModeHandler/IframeModeHandler';
import { addOptionsListener, getOptions, setOptions } from '../Handlers/studio/OptionsHandler/IframeOptionsHandler';
import { addThemeListener, getTheme } from '../Handlers/studio/ThemeHandler/IframeThemeHandler';
import { addTokensListener, getTokens } from '../Handlers/studio/TokensHandler/IframeTokensHandler';

const DashboardExtensionAPI = {
    addDataSourcesListener,
    getDataSources,
    addModeListener,
    getMode,
    addDimensionsListener,
    getDimensions,
    addOptionsListener,
    getOptions,
    setOptions,
    addThemeListener,
    getTheme,
    addTokensListener,
    getTokens,
    addDrilldownListener,
    triggerDrilldown,
    addErrorListener,
    getError,
    setError,
    clearError,
} as const;

export function initDashboardExtensionAPI() {
    const globalWithExtensionAPI = globalThis as typeof globalThis & {
        DashboardExtensionAPI?: typeof DashboardExtensionAPI;
    };
    globalWithExtensionAPI.DashboardExtensionAPI = new Proxy(DashboardExtensionAPI, {
        get(target, prop: keyof typeof DashboardExtensionAPI, receiver) {
            return (
                Reflect.get(target, prop, receiver) ??
                (() => {
                    throw new Error(`This version of Dashboard Studio does not implement ${String(prop)}`);
                })
            );
        },
        set() {
            throw new Error('DashboardExtensionAPI is read-only');
        },
    });
}
