import { registerMessageHandler } from '../../../MessageHandler/MessageHandler';
import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { DimensionsMessageType, type DimensionsUpdateMessage } from './common';

const STATE_KEY = 'dimensionsState';

export function handleDimensionsUpdate(event: MessageEvent<DimensionsUpdateMessage>) {
    const { data } = event.data;
    setIframeState(STATE_KEY, data, true);
}

export function initIframeDimensionsHandler() {
    registerMessageHandler(DimensionsMessageType.DimensionsUpdate, handleDimensionsUpdate);
}

export function addDimensionsListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}

export function getDimensions(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}
