import { registerMessageHandler } from '../../../MessageHandler/MessageHandler';
import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { ThemeMessageType, type ThemeUpdateMessage } from './common';

const STATE_KEY = 'themeState';

export function handleThemeUpdate(event: MessageEvent<ThemeUpdateMessage>) {
    const { data } = event.data;
    const themeMetaTag = document.querySelector('meta[name="color-scheme"]');
    if (themeMetaTag) {
        themeMetaTag.setAttribute('content', data.theme);
    }
    setIframeState(STATE_KEY, data, true);
}

export function initIframeThemeHandler() {
    registerMessageHandler(ThemeMessageType.ThemeUpdate, handleThemeUpdate);
}

export function addThemeListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}

export function getTheme(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}
