import type { DrilldownArgs, DrilldownPayload } from '../../../common/types';
import { getParentOrigin } from '../../../common/utils';
import { DEFAULT_DRILLDOWN_ACTION, DrilldownMessageType, type HandleDrilldownMessage } from './constants';

export function handleIframeDrilldown(drilldownArgs: DrilldownArgs) {
    const message: HandleDrilldownMessage = {
        type: DrilldownMessageType.HandleDrilldown,
        ...drilldownArgs,
        originalEvent: { type: drilldownArgs.originalEvent?.type ?? 'click' },
    };
    window.parent.postMessage(message, getParentOrigin());
}

export function addDrilldownListener({
    node,
    action,
    payloadCallback,
}: { node: HTMLElement; action?: string; payloadCallback?: () => DrilldownPayload }) {
    const studioAction = action ? `${action}.click` : DEFAULT_DRILLDOWN_ACTION;
    node.addEventListener('click', (e) => {
        handleIframeDrilldown({
            action: studioAction,
            payload: payloadCallback ? payloadCallback() : {},
            originalEvent: e,
        });
    });
}
