export type BaseMessage = {
    type: string;
};

export type MessageHandler<T extends BaseMessage> = ((event: MessageEvent<T>) => void) & {
    iframeRef?: React.RefObject<HTMLIFrameElement>;
};
export const messageHandlers = new Map<string, Set<MessageHandler<any>>>();

export function handleMessage(event: MessageEvent) {
    const { type } = event.data;
    const handlersSet = messageHandlers.get(type) ?? new Set();
    let handled = false;
    for (const handler of handlersSet) {
        if (event.source === handler.iframeRef?.current?.contentWindow || handler.iframeRef === undefined) {
            handled = true;
            handler(event);
        }
    }
    if (!handled) {
        console.warn(`No handler found for message type: ${type}`);
    }
}

export function registerMessageHandler<T extends BaseMessage>(
    type: string,
    handler: MessageHandler<T>,
    iframeRef?: React.RefObject<HTMLIFrameElement>,
) {
    handler.iframeRef = iframeRef;
    const handlersSet = messageHandlers.get(type) ?? new Set();
    handlersSet.add(handler);
    messageHandlers.set(type, handlersSet);
}

export function removeMessageHandler<T extends BaseMessage>(type: string, handler: MessageHandler<T>) {
    const handlersSet = messageHandlers.get(type);
    if (handlersSet) {
        handlersSet.delete(handler);
    }
}
