import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { getParentOrigin } from '../../../common/utils';
import { type ErrorClearMessage, ErrorMessageType, type ErrorUpdateMessage } from './common';

const STATE_KEY = 'errorState';

export function setError(message: string): void {
    const errorState = { message };
    setIframeState(STATE_KEY, errorState.message, true);

    const msg: ErrorUpdateMessage = {
        type: ErrorMessageType.ErrorUpdate,
        data: errorState,
    };
    window.parent.postMessage(msg, getParentOrigin());
}

export function clearError(): void {
    setIframeState(STATE_KEY, null, true);

    const msg: ErrorClearMessage = {
        type: ErrorMessageType.ErrorClear,
    };
    window.parent.postMessage(msg, getParentOrigin());
}

export function getError(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}

export function addErrorListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}
