import { registerMessageHandler } from '../MessageHandler/MessageHandler';
import { getParentOrigin } from '../common/utils';
import {
    type ProxyFetchErrorMessage,
    type ProxyFetchRequestMessage,
    type ProxyFetchResponseMessage,
    ProxyMessageType,
} from './constants';

export const pendingFetchRequests = new Map<
    number,
    { resolve: (value: Response) => void; reject: (reason: unknown) => void }
>();

export function handleFetchError(event: MessageEvent<ProxyFetchErrorMessage>) {
    const { requestId } = event.data;

    const request = pendingFetchRequests.get(requestId);

    if (!request) {
        return;
    }

    pendingFetchRequests.delete(requestId);
    request.reject(new Error(event.data.error));
}

export function handleFetchResponse(event: MessageEvent<ProxyFetchResponseMessage>) {
    const { requestId } = event.data;

    const request = pendingFetchRequests.get(requestId);

    if (!request) {
        return;
    }

    pendingFetchRequests.delete(requestId);
    const { arrayBuffer, init } = event.data;
    const response = new Response(arrayBuffer, init);
    request.resolve(response);
}

export function initIframeFetchSetup() {
    const customWindow = window as typeof window & { originalFetch: typeof fetch };

    let requestId = 0;
    // Store the original fetch function
    customWindow.originalFetch = window.fetch;
    const parentOrigin = getParentOrigin();

    // @ts-ignore Override fetch with our conditional proxied version
    customWindow.fetch = (resource: string | Request, options: RequestInit = {}): Promise<Response> => {
        const resolvedUrl = resource instanceof Request ? resource.url : resource;
        const absoluteUrl = new URL(resolvedUrl, parentOrigin);

        // Use proxy for URLs with the same origin as the parent
        if (absoluteUrl.origin === parentOrigin) {
            const proxyOptions: RequestInit =
                resource instanceof Request
                    ? { method: resource.method, headers: Object.fromEntries(resource.headers.entries()), ...options }
                    : options;

            return new Promise((resolve, reject) => {
                requestId++;

                pendingFetchRequests.set(requestId, { resolve, reject });

                // Send the fetch request to the parent
                window.parent.postMessage(
                    {
                        type: ProxyMessageType.FetchProxyRequest,
                        requestId,
                        url: absoluteUrl.href,
                        options: proxyOptions,
                    } as ProxyFetchRequestMessage,
                    getParentOrigin(),
                );
            });
        }

        return customWindow.originalFetch(resource, options);
    };

    registerMessageHandler(ProxyMessageType.FetchProxyResponse, handleFetchResponse);
    registerMessageHandler(ProxyMessageType.FetchProxyError, handleFetchError);
}
