import { getParentOrigin } from '../common/utils';
import { handleMessage } from './MessageHandler';

function handleIframeMessage(event: MessageEvent) {
    if (event.origin !== getParentOrigin()) {
        return;
    }

    return handleMessage(event);
}

export function initIframeMessageHandler() {
    return window.addEventListener('message', handleIframeMessage);
}

export function destroyIframeMessageHandler() {
    return window.removeEventListener('message', handleIframeMessage);
}
