import type { TokenState } from '@splunk/dashboard-types';
import type Backbone from 'backbone';

export enum CustomVizVersion {
    legacy = 1,
    studio = 2,
}

/**
 * Retrieves the parent origin from the iframe's base URI.
 */
export function getParentOrigin() {
    const baseURI = document.baseURI;
    const url = new URL(baseURI);
    return url.origin;
}

/**
 * Returns the root element in the IFRAME
 */
export function getRootElement() {
    return document.body.firstChild as HTMLElement | null;
}

/**
 * Converts arrayBuffer to Base64
 * We're chunking 8KB at a time as loading a larger chunk or the whole
 * file size causes the stack to overflow. This seems to work fine.
 *
 * @param arrayBuffer
 * @returns base64 string
 */
export function arrayBufferToBase64(arrayBuffer: ArrayBuffer): string {
    const uint8Array = new Uint8Array(arrayBuffer);
    let binary = '';
    const chunk = 8192; // Process 8KB at a time

    for (let i = 0; i < uint8Array.length; i += chunk) {
        const slice = uint8Array.slice(i, i + chunk) as unknown as number[];
        binary += String.fromCharCode.apply(null, slice);
    }

    return btoa(binary);
}

export function getCustomVizVersion(): CustomVizVersion {
    return Number(getRootElement()?.getAttribute('data-custom-viz-version') ?? CustomVizVersion.legacy);
}

export interface TokenRegistry extends Backbone.Model {
    initialize: () => void;
    registerInstance: (id: string, component: Backbone.Model, options?: Record<string, unknown>) => void;
    revokeInstance: (id: string, options?: Record<string, unknown>) => void;
    hasInstance: (id: string) => boolean;
    getInstance: (id: string, options?: { create?: boolean }) => Backbone.Model;
    getInstances: () => Backbone.Model[];
    getInstanceNames: () => string[];
}

export const createTokenRegistry = (backbone: typeof Backbone): TokenRegistry => {
    // Taken from web_v2/search_mrsparkle/exposed/js/splunkjs/mvc/registry.js
    const Registry = backbone.Model.extend({
        initialize: function () {
            this.registerInstance('default', new backbone.Model());
        },
        registerInstance: function (id: string, component: Backbone.Model, options: Record<string, unknown> = {}) {
            if (!id) {
                throw new Error('You must pass in an ID when registering an instance.');
            }
            if (this.has(id) && !options.replace) {
                throw new Error(`Already have instance with id: ${id}`);
            }
            this.set(id, component, options);
            return component;
        },
        revokeInstance: function (id: string, options?: Record<string, unknown>) {
            this.unset(id, options);
        },
        hasInstance: function (id: string) {
            return this.has(id);
        },
        getInstance: function (id: string, options: { create?: boolean } = {}) {
            if (!this.has(id)) {
                if (options.create) {
                    this.registerInstance(id, new backbone.Model());
                }
            }

            return this.get(id);
        },
        getInstances: function () {
            return Object.values(this.attributes);
        },
        getInstanceNames: function () {
            return Object.keys(this.attributes);
        },
    });
    return new Registry();
};

export const mockRequireJsModules = (modules: Record<string, unknown>) => {
    window.requirejs?.exposeModules({
        modules,
        isAllowedList: true,
        blockPrivateImports: true,
    });
};

export const setTokenBinding = ({
    backbone,
    tokenBinding,
    tokenRegistry,
}: { backbone: typeof Backbone; tokenBinding: TokenState; tokenRegistry: TokenRegistry }) => {
    Object.entries(tokenBinding).forEach(([tokenNamespace, tokenValues]) => {
        if (!tokenRegistry.hasInstance(tokenNamespace)) {
            tokenRegistry.registerInstance(tokenNamespace, new backbone.Model());
        }
        const tokenNamespaceModel = tokenRegistry.getInstance(tokenNamespace);
        tokenNamespaceModel.set(tokenValues);
        tokenNamespaceModel.keys().forEach((key) => {
            if (!(key in tokenValues)) {
                tokenNamespaceModel.unset(key);
            }
        });
    });
};

export function getMetaTagData(key: string) {
    const metaData = document.querySelector(`meta[name="${key}"]`);
    const content = metaData?.getAttribute('content') ?? null;
    return content;
}
