import { registerMessageHandler } from '../../../MessageHandler/MessageHandler';
import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { DataSourcesMessageType, type DataSourcesUpdateMessage } from './common';

const STATE_KEY = 'dataSourcesState';

export function handleDataSourcesUpdate(event: MessageEvent<DataSourcesUpdateMessage>) {
    const { data } = event.data;
    setIframeState(STATE_KEY, data, true);
}

export function initIframeDataSourcesHandler() {
    registerMessageHandler(DataSourcesMessageType.DataSourcesUpdate, handleDataSourcesUpdate);
}

export function addDataSourcesListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}

export function getDataSources(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}
