import { toPng } from 'html-to-image';
import { registerMessageHandler } from '../MessageHandler/MessageHandler';
import { getParentOrigin, getRootElement } from '../common/utils';
import {
    type ContentExporterRequestMessage,
    type ContentExporterSuccessMessage,
    ContentExporterType,
} from './constants';

export async function exportAsPng(event: MessageEvent<ContentExporterRequestMessage>) {
    const node = getRootElement()!;
    try {
        const dataUri = await toPng(node);
        const message: ContentExporterSuccessMessage = {
            type: ContentExporterType.Success,
            id: event.data.id,
            dataUri,
        };
        window.parent.postMessage(message, getParentOrigin());
    } catch (error) {
        const errorMessage = {
            type: ContentExporterType.Error,
            id: event.data.id,
            error: (error as Record<string, string>).message ?? 'Unknown error',
        };
        window.parent.postMessage(errorMessage, getParentOrigin());
    }
}

export function initContentExporter() {
    registerMessageHandler(ContentExporterType.Request, exportAsPng as unknown as () => void);
}
