import { getParentOrigin } from '../../../common/utils';
import { type FocusHandlerFocusEventMessage, FocusHandlerType } from './constants';

export function initIframeFocusHandler() {
    window.addEventListener('focus', () => {
        const message: FocusHandlerFocusEventMessage = {
            type: FocusHandlerType.FocusEvent,
        };
        window.parent.postMessage(message, getParentOrigin());
    });
}
