import { getParentOrigin } from '@splunk/enterprise-dashboard-custom-viz/common/utils';
import { registerMessageHandler } from '../../../MessageHandler/MessageHandler';
import { type IframeState, getIframeState, setIframeState, subscribeToIframeState } from '../../../StateManager/state';
import { getMode } from '../ModeHandler/IframeModeHandler';
import { OptionsMessageType, type OptionsUpdateMessage } from './common';

const STATE_KEY = 'optionsState';

export function handleOptionsUpdate(event: MessageEvent<OptionsUpdateMessage>) {
    const { data } = event.data;
    setIframeState(STATE_KEY, data, true);
}

export function initIframeOptionsHandler() {
    registerMessageHandler(OptionsMessageType.OptionsUpdate, handleOptionsUpdate);
}

export function addOptionsListener(
    callback: (state: IframeState[typeof STATE_KEY]) => void,
    options: { invokeImmediately?: boolean; signal?: AbortSignal } = {},
) {
    return subscribeToIframeState({
        key: STATE_KEY,
        callback,
        options,
    });
}

export function getOptions(): IframeState[typeof STATE_KEY] {
    return getIframeState(STATE_KEY);
}

export function setOptions(options: Record<string, unknown>) {
    if (getMode()?.mode === 'edit') {
        const message: OptionsUpdateMessage = {
            type: OptionsMessageType.OptionsUpdate,
            data: {
                options,
            },
        };
        globalThis.parent.postMessage(message, getParentOrigin());
    } else {
        throw new Error('Cannot set options in view mode');
    }
}
